<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\Doctor;use Illuminate\Http\Request;
class DoctorServiceSettingsController extends Controller{public function show(){return response()->json(['success'=>true,'data'=>Doctor::where('user_id',auth()->id())->firstOrFail()->only(['offers_in_person_consultation','offers_text_consultation','offers_video_consultation','offers_home_visit','in_person_fee','text_consultation_fee','video_consultation_fee','home_visit_fee'])]);}public function update(Request $r){$d=Doctor::where('user_id',auth()->id())->firstOrFail();$v=$r->validate(['offers_in_person_consultation'=>'required|boolean','offers_text_consultation'=>'required|boolean','offers_video_consultation'=>'required|boolean','offers_home_visit'=>'required|boolean','in_person_fee'=>'required|numeric|min:0','text_consultation_fee'=>'required|numeric|min:0','video_consultation_fee'=>'required|numeric|min:0','home_visit_fee'=>'required|numeric|min:0']);$d->update($v);return response()->json(['success'=>true,'data'=>$d->fresh(),'message'=>'تنظیمات خدمات و تعرفه‌ها ذخیره شد']);}}
